  n += put(g, x, 2, z + 1, B.slab("smooth_quartz", "bottom")) + put(g, x + 1, 2, z + 1, B.slab("smooth_quartz", "bottom"));
  n += put(g, x, 2, z + 2, B.stairs("smooth_quartz", "south", "bottom"));
  n += put(g, x + 1, 2, z + 2, B.block("cauldron")) + put(g, x + 1, 3, z + 2, B.pane());
  return n;
}

